\caption{$\mathtt{GetMatrixSequence}$}
\label{alg:matrix}
\KwIn{indices $i_1,\dots,i_{j-1}\in[n]$ for some $j\ge 1$.}
\KwOut{$M_1,\dots,M_j$, which are $(t-1)k\times (t-1)k$ matrices over $\mathbb{F}_q(X_1,X_2,\dots,X_n)$.}
$B\gets \emptyset$, $i_0\gets \perp$, $\ell_0\gets\perp$\;
\For{$\ell=1,\dots,j$}{ \label{line:outer-loop}
  \tcp*[l]{$M_\ell$ depends only on $i_1,\dots,i_{\ell-1}$}
  \If{$\ell > 1$}{
    \tcp*[l]{Fetch new index from bank $B$}
    $\tau\gets$ the type of $i_{\ell-1}$\label{line:tau}\;
    $s\gets$ number of indices among $i_{\ell_0},i_{\ell_0+1},\dots,i_{\ell-1}$ that are type $\tau$ \label{line:s}\;
    $i_{\ell-1}'\gets$ the $s$-th smallest element of $B$ that has type $\tau$\;
    \If{$i_{\ell-1}'$ \textrm{is defined}}{
      $M_\ell\gets$ the matrix obtained from $M_{\ell-1}$ by replacing all copies of $X_{i_{\ell-1}}$ with $X_{i_{\ell-1}'}$
      \label{line:ml}
    }
  }
  \If{$M_\ell$ \textrm{not yet defined}}{
    \tcp*[l]{Refresh bank $B$}
    $B\gets \emptyset$\;
    \For{$\tau=1,\dots,2^t$}{
      $B\gets B \cup \{\text{largest $\floor{r/2^t}$ indices of type $\tau$ in $[n]\setminus\{i_1,\dots,i_{\ell-1}\}$}\}$
    (if there are less than $\floor{r/2^t}$ indices of type $\tau$, then $B$ contains all such indices) \label{line:B}\;
    }
    $M_\ell\gets $ lexicographically smallest nonsingular $(t-1)k\times (t-1)k$ submatrix of $\mathsf{RIM}_{\mathcal{H}}^{B\cup \{i_1,\dots,i_{\ell-1}\}}$ \label{line:ml2}\;
    $\ell_0\gets \ell$ \tcp{new refresh index} \label{line:refresh-index}\;
  }
}
\Return{$M_1,\dots,M_j$}

\caption{$\mathtt{GetCertificate}$}
\label{alg:certificate}
\KwIn{Evaluation points $(\alpha_1,\dots,\alpha_n) \in \mathbb{F}_q^n$.}
\KwOut{A ``certificate'' $(i_1,\dots,i_r) \in [n]^r$.}
\For{$j=1,\dots,r$}{
  \tcp*[l]{$M_1,\dots,M_{j-1}$ stay the same, $M_j$ is now defined}
  $M_1,\dots,M_j = \mathtt{GetMatrixSequence}(i_1,\dots,i_{j-1})$\;
  $i_j \gets $ smallest index $i$ such that $M_j(X_{\le i}=\alpha_{\le i})$ is singular\label{line:ij}\;
  \If{$i_j$\text{ not defined}}{
    \Return{$\perp$}
  }
}
\Return{$(i_1,\dots,i_r)$}

